import { EventEmitter } from 'events';
import * as crypto from 'crypto';

interface Message {
  id: string;
  sender: string;
  recipient: string;
  content: string;
  timestamp: number;
  nonce: number;
}

interface CircuitState {
  failures: number;
  lastFailure: number;
  state: 'closed' | 'open' | 'half-open';
}

class MessageQueue {
  private pending: Message[] = [];
  private processing: boolean = false;

  enqueue(msg: Message): number {
    const position = this.pending.length;
    this.pending.push(msg);
    return position;
  }

  peek(): Message | undefined {
    return this.pending[0];
  }

  dequeue(): Message | undefined {
    return this.pending.shift();
  }

  getAll(): Message[] {
    return [...this.pending];
  }

  get length(): number {
    return this.pending.length;
  }
}

class CircuitBreaker {
  private state: CircuitState = { failures: 0, lastFailure: 0, state: 'closed' };
  private readonly threshold: number = 3;
  private readonly resetTimeout: number = 5000;

  canExecute(): boolean {
    if (this.state.state === 'closed') return true;
    if (this.state.state === 'open') {
      const elapsed = Date.now() - this.state.lastFailure;
      if (elapsed > this.resetTimeout) {
        this.state.state = 'half-open';
        return true;
      }
      return false;
    }
    return true;
  }

  recordSuccess(): void {
    this.state.failures = 0;
    this.state.state = 'closed';
  }

  recordFailure(): void {
    this.state.failures++;
    this.state.lastFailure = Date.now();
    if (this.state.failures >= this.threshold) {
      this.state.state = 'open';
    }
  }

  getState(): string {
    return this.state.state;
  }
}

class ChatServer extends EventEmitter {
  private queues: Map<string, MessageQueue> = new Map();
  private circuitBreakers: Map<string, CircuitBreaker> = new Map();
  private messageLog: Message[] = [];
  private nonceRegistry: Map<string, Set<number>> = new Map();

  constructor() {
    super();
  }

  private getQueue(channel: string): MessageQueue {
    if (!this.queues.has(channel)) {
      this.queues.set(channel, new MessageQueue());
    }
    return this.queues.get(channel)!;
  }

  private getCircuitBreaker(channel: string): CircuitBreaker {
    if (!this.circuitBreakers.has(channel)) {
      this.circuitBreakers.set(channel, new CircuitBreaker());
    }
    return this.circuitBreakers.get(channel)!;
  }

  private validateNonce(sender: string, nonce: number): boolean {
    if (!this.nonceRegistry.has(sender)) {
      this.nonceRegistry.set(sender, new Set());
    }
    const senderNonces = this.nonceRegistry.get(sender)!;
    if (senderNonces.has(nonce)) {
      return false;
    }
    senderNonces.add(nonce);
    return true;
  }

  submitMessage(channel: string, msg: Message): { success: boolean; position?: number; error?: string } {
    const cb = this.getCircuitBreaker(channel);

    if (!cb.canExecute()) {
      return { success: false, error: 'Circuit breaker open - channel temporarily unavailable' };
    }

    if (!this.validateNonce(msg.sender, msg.nonce)) {
      cb.recordFailure();
      return { success: false, error: 'Duplicate nonce detected' };
    }

    const queue = this.getQueue(channel);
    const position = queue.enqueue(msg);

    this.emit('message_queued', { channel, position, messageId: msg.id });

    return { success: true, position };
  }

  processChannel(channel: string): Message[] {
    const queue = this.getQueue(channel);
    const cb = this.getCircuitBreaker(channel);
    const delivered: Message[] = [];

    while (queue.length > 0) {
      const msg = queue.dequeue()!;
      try {
        this.deliverMessage(msg);
        cb.recordSuccess();
        delivered.push(msg);
      } catch (e) {
        cb.recordFailure();
        break;
      }
    }

    return delivered;
  }

  inspectQueue(channel: string, requestor: string): Message[] {
    const queue = this.getQueue(channel);
    const pending = queue.getAll();
    // Only return messages where requestor is the recipient
    return pending
      .filter(m => m.recipient === requestor)
      .map(m => ({ ...m }));
  }

  private deliverMessage(msg: Message): void {
    this.messageLog.push(msg);
    this.emit('message_delivered', { messageId: msg.id, recipient: msg.recipient, timestamp: Date.now() });
  }

  getChannelStatus(channel: string): { queueDepth: number; circuitState: string } {
    const queue = this.getQueue(channel);
    const cb = this.getCircuitBreaker(channel);
    return { queueDepth: queue.length, circuitState: cb.getState() };
  }
}

export { ChatServer, Message, MessageQueue, CircuitBreaker };
